const mat3 LINEAR_SRGB_TO_LINEAR_DISPLAY_P3 = mat3(
	vec3( 0.8224621, 0.177538, 0.0 ),
	vec3( 0.0331941, 0.9668058, 0.0 ),
	vec3( 0.0170827, 0.0723974, 0.9105199 )
);
const mat3 LINEAR_DISPLAY_P3_TO_LINEAR_SRGB = mat3(
	vec3( 1.2249401, - 0.2249404, 0.0 ),
	vec3( - 0.0420569, 1.0420571, 0.0 ),
	vec3( - 0.0196376, - 0.0786361, 1.0982735 )
);
vec4 LinearSRGBToLinearDisplayP3( in vec4 value ) {
	return vec4( value.rgb * LINEAR_SRGB_TO_LINEAR_DISPLAY_P3, value.a );
}
vec4 LinearDisplayP3ToLinearSRGB( in vec4 value ) {
	return vec4( value.rgb * LINEAR_DISPLAY_P3_TO_LINEAR_SRGB, value.a );
}
vec4 LinearTransferOETF( in vec4 value ) {
	return value;
}
vec4 sRGBTransferOETF( in vec4 value ) {
	return vec4( mix( pow( value.rgb, vec3( 0.41666 ) ) * 1.055 - vec3( 0.055 ), value.rgb * 12.92, vec3( lessThanEqual( value.rgb, vec3( 0.0031308 ) ) ) ), value.a );
}
vec4 LinearToLinear( in vec4 value ) {
	return value;
}
vec4 LinearTosRGB( in vec4 value ) {
	return sRGBTransferOETF( value );
}
vec4 linearToOutputTexel( vec4 value ) { return ( LinearTransferOETF( value ) ); }


                uniform Global{vec2 resolution;vec2 resolutionUI;float aspect;float time;float dtRatio;};
                float efit(float x,float a1,float a2,float b1,float b2){return b1+((x-a1)*(b2-b1))/(a2-a1);}float fit(float x,float a1,float a2,float b1,float b2){return clamp(efit(x,a1,a2,b1,b2),min(b1,b2),max(b1,b2));}float fit01(float x,float a1,float a2){return fit(x,0.0,1.0,a1,a2);}float fit10(float x,float a1,float a2){return fit(x,1.0,0.0,a1,a2);}float fit11(float x,float a1,float a2){return fit(x,-1.0,1.0,a1,a2);}vec3 efit(vec3 x,vec3 a1,vec3 a2,vec3 b1,vec3 b2){return b1+((x-a1)*(b2-b1))/(a2-a1);}vec3 fit(vec3 x,vec3 a1,vec3 a2,vec3 b1,vec3 b2){return clamp(efit(x,a1,a2,b1,b2),min(b1,b2),max(b1,b2));}vec3 fit01(vec3 x,vec3 a1,vec3 a2){return fit(x,vec3(0.0),vec3(1.0),a1,a2);}vec3 fit10(vec3 x,vec3 a1,vec3 a2){return fit(x,vec3(1.0),vec3(0.0),a1,a2);}vec3 fit11(vec3 x,vec3 a1,vec3 a2){return fit(x,vec3(-1.0),vec3(1.0),a1,a2);}

                float line(vec2 uv, vec2 point1, vec2 point2) {
                    vec2 pa = uv - point1, ba = point2 - point1;
                    pa.x *= aspect;
                    ba.x *= aspect;
                    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
                    return length(pa - ba * h);
                }

                float cubicIn(float t) { return t * t * t; }

                varying vec2 vUv;

                uniform sampler2D tBuffer;
                uniform sampler2D tAdvect;
                uniform vec2 uSplatCoords;
                uniform vec2 uSplatPrevCoords;
                uniform float uSplatRadius;

                void main() {
                    vec2 uv = vUv;

                    vec2 invResolution = 1.0 / vec2(textureSize(tBuffer, 0));

                    // advect by noise
                    vec2 noiseUv = vUv;
                    vec2 advect = (texture2D(tAdvect, noiseUv * 3.0).xy * 2.0 - 1.0) * 1.0;
                    uv += advect * invResolution;

                    // wave propagation
                    float wavespeed = 1.0;
                    vec2 offset = invResolution * wavespeed;
                    float l = texture2D(tBuffer, uv - vec2(offset.x, 0.0)).r;
                    float r = texture2D(tBuffer, uv + vec2(offset.x, 0.0)).r;
                    float t = texture2D(tBuffer, uv + vec2(0.0, offset.y)).r;
                    float b = texture2D(tBuffer, uv - vec2(0.0, offset.y)).r;
                    float nextVal = max(max(max(l, r), t), b);

                    // mouse line splat
                    float radius = 0.05 * smoothstep(0.1, 1.0, uSplatRadius);
                    float splat = cubicIn(clamp(1.0 - line(vUv, uSplatPrevCoords.xy, uSplatCoords.xy) / radius, 0.0, 1.0));
                    nextVal += splat;

                    // damping and clamp
                    nextVal *= 0.985;
                    nextVal = min(nextVal, 1.0);

                    vec4 prev = texture2D(tBuffer, uv);
                    float rim = nextVal - prev.r;

                    float rimLerp = prev.b + rim;
                    rimLerp *= 0.9;

                    gl_FragColor = vec4(nextVal, rim, rimLerp, 1.0);
                }

