                float efit(float x,float a1,float a2,float b1,float b2){return b1+((x-a1)*(b2-b1))/(a2-a1);}float fit(float x,float a1,float a2,float b1,float b2){return clamp(efit(x,a1,a2,b1,b2),min(b1,b2),max(b1,b2));}float fit01(float x,float a1,float a2){return fit(x,0.0,1.0,a1,a2);}float fit10(float x,float a1,float a2){return fit(x,1.0,0.0,a1,a2);}float fit11(float x,float a1,float a2){return fit(x,-1.0,1.0,a1,a2);}vec3 efit(vec3 x,vec3 a1,vec3 a2,vec3 b1,vec3 b2){return b1+((x-a1)*(b2-b1))/(a2-a1);}vec3 fit(vec3 x,vec3 a1,vec3 a2,vec3 b1,vec3 b2){return clamp(efit(x,a1,a2,b1,b2),min(b1,b2),max(b1,b2));}vec3 fit01(vec3 x,vec3 a1,vec3 a2){return fit(x,vec3(0.0),vec3(1.0),a1,a2);}vec3 fit10(vec3 x,vec3 a1,vec3 a2){return fit(x,vec3(1.0),vec3(0.0),a1,a2);}vec3 fit11(vec3 x,vec3 a1,vec3 a2){return fit(x,vec3(-1.0),vec3(1.0),a1,a2);}
                float treadmill(float p,float margin){float n=fract((p+margin)/(2.0*margin));return n*2.0*margin-margin;}vec2 treadmill(vec2 p,vec2 margin){vec2 n=fract((p+margin)/(2.0*margin));return n*2.0*margin-margin;}vec3 treadmill(vec3 p,vec3 margin){vec3 n=fract((p+margin)/(2.0*margin));return n*2.0*margin-margin;}vec4 treadmill(vec4 p,vec4 margin){vec4 n=fract((p+margin)/(2.0*margin));return n*2.0*margin-margin;}

                attribute vec3 random;

                varying float vLightFalloff;
                varying vec3 vRandom;

                uniform float uRotation;
                uniform sampler2D tSim;

                void main() {
                    vRandom = random;

                    float t = time * 0.05;
                    vec3 pos = position;
                    pos.x += sin(t * 0.4 + position.y * 2.5);
                    pos.y += sin(t * 0.2 + position.x * 2.5);
                    pos.y += time * random.z * 0.2;
                    pos = treadmill(pos, vec3(1.0));
                    // pos.z += sin(t * 0.3 + position.z * 2.5);

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);

                    vec2 ndc = gl_Position.xy / gl_Position.w;
                    vec2 fluid = texture(tSim, ndc * 0.5 + 0.5).rb;
                    float sim = fit(fluid.y, 1e-8, 0.3, 0.0, 1.0);
                    // sim = 1.;

                    // scale larger with screen gradient
                    float size = mix(3.0, 10.0, random.x * sim);
                    gl_PointSize = size * (resolution.y * 0.002);

                    // random flicker
                    float flick = sin(time * 0.8 + random.y * 12.43) * 0.5 + 0.5;
                    flick *= sin(time * 1.73 + random.z * 7.16) * 0.5 + 0.5;
                    vLightFalloff = mix(0.5, 1.0, flick) * sim;
                }

